mapper.update:
update p_generation_step set status = 'RUNNING', attempt_no = attempt_no + 1, lease_epoch = lease_epoch + 1,
    lease_owner = #{workerId}, lease_expires_at = date_add(utc_timestamp(3), interval 5 minute), heartbeat_at = utc_timestamp(3), updated_at = utc_timestamp(3)
where id = #{stepId} and status = 'READY' and lease_epoch = #{leaseEpoch}

update p_generation_step set status = #{status}, error_code = #{errorCode}, heartbeat_at = utc_timestamp(3), updated_at = utc_timestamp(3)
where account_id = #{accountId} and task_id = #{taskId} and id = #{stepId} and lease_owner = #{workerId}
  and lease_epoch = #{leaseEpoch} and lease_expires_at > utc_timestamp(3)

update p_generation_step set status = #{status}, lease_expires_at = null, heartbeat_at = utc_timestamp(3), updated_at = utc_timestamp(3)
where account_id = #{accountId} and task_id = #{taskId} and id = #{stepId} and lease_owner = #{workerId}
  and lease_epoch = #{leaseEpoch} and lease_expires_at > utc_timestamp(3)

update p_generation_attempt set status = #{status}, completed_at = coalesce(completed_at, utc_timestamp(3)), updated_at = utc_timestamp(3)
where id = #{attemptId} and step_id = #{stepId} and attempt_no = #{attemptNo} and lease_epoch = #{leaseEpoch}
  and status = #{status}
